// components/LikeButton.tsx
'use client';

import { useOptimistic } from 'react';
import { likePost } from '@/actions/likePost';

type LikeButtonProps = {
  postId: string;
  initialLikes: number;
  isLiked: boolean;
};

export function LikeButton({ postId, initialLikes, isLiked }: LikeButtonProps) {
  const [optimisticLikes, setOptimisticLikes] = useOptimistic(
    { likes: initialLikes, isLiked },
    (state, newIsLiked: boolean) => ({
      likes: newIsLiked ? state.likes + 1 : state.likes - 1,
      isLiked: newIsLiked,
    })
  );

  async function handleLike() {
    // 楽観的更新（即座にUIを更新）
    setOptimisticLikes(!optimisticLikes.isLiked);

    // Server Actionsを実行
    const result = await likePost(postId, !optimisticLikes.isLiked);

    // エラー時は自動的に元に戻る
    if (!result.isSuccess) {
      console.error(result.errorMessage);
    }
  }

  return (
    <button onClick={handleLike}>
      {optimisticLikes.isLiked ? '❤️' : '🤍'} {optimisticLikes.likes}
    </button>
  );
}

// components/SearchForm.tsx
'use client';

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { searchProducts } from '@/apis/products.client';

type SearchFormProps = {
  initialQuery: string;
};

export function SearchForm({ initialQuery }: SearchFormProps) {
  const queryClient = useQueryClient();

  const mutation = useMutation({
    mutationFn: (query: string) => searchProducts(query),
    onSuccess: (data, variables) => {
      // 成功時にクエリキャッシュを無効化
      queryClient.invalidateQueries({ queryKey: ['products', 'search'] });
    },
    onError: (error) => {
      console.error('Search failed:', error);
    },
  });

  function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const query = formData.get('query') as string;
    mutation.mutate(query);
  }

  return (
    <form onSubmit={handleSubmit}>
      <input name="query" defaultValue={initialQuery} />
      <button type="submit" disabled={mutation.isPending}>
        {mutation.isPending ? 'Searching...' : 'Search'}
      </button>
      {mutation.isError && <p>Error: {mutation.error.message}</p>}
    </form>
  );
}

// actions/createPost.ts
'use server';

import { updateTag } from 'next/cache';
import { createPostInDB, notifyFollowers } from '@/apis/posts.server';
import { Result } from '@/types/result';

export async function createPost(
  userId: string,
  data: PostCreateInput
): Promise<Result<Post>> {
  try {
    // 1. バリデーション
    const validated = postSchema.parse(data);

    // 2. トランザクション開始
    const post = await db.transaction(async (tx) => {
      // 2-1. 投稿を作成
      const newPost = await createPostInDB(tx, userId, validated);

      // 2-2. フォロワーに通知
      await notifyFollowers(tx, userId, newPost.id);

      return newPost;
    });

    // 3. 複数のキャッシュタグを無効化
    updateTag('posts');
    updateTag(`user-${userId}-posts`);
    updateTag('timeline');

    return { isSuccess: true, data: post };
  } catch (error) {
    return {
      isSuccess: false,
      errorMessage: 'Failed to create post',
    };
  }
}

// components/ProductForm.tsx
'use client';

import { useQueryClient } from '@tanstack/react-query';
import { updateProduct } from '@/actions/updateProduct';

type ProductFormProps = {
  productId: string;
};

export function ProductForm({ productId }: ProductFormProps) {
  const queryClient = useQueryClient();

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = Object.fromEntries(formData);

    // Server Actionsで更新（updateTagでサーバー側キャッシュも無効化）
    const result = await updateProduct(productId, data);

    if (result.isSuccess) {
      // TanStack Queryのキャッシュも手動で無効化
      queryClient.invalidateQueries({ queryKey: ['products', productId] });
      queryClient.invalidateQueries({ queryKey: ['products', 'list'] });
    } else {
      console.error(result.errorMessage);
    }
  }

  return <form onSubmit={handleSubmit}>{/* form fields */}</form>;
}
